import React from 'react';
import '../../styles/itineraryCSS/Itinerary.css';
import bg1 from '../../assets/uploads/locations/1/1-intro.jpg';
import bg2 from '../../assets/uploads/locations/2/2-intro.jpg';
import bg3 from '../../assets/uploads/locations/3/3-intro.jpg';
import bg4 from '../../assets/uploads/locations/4/4-intro.jpg';
import bg5 from '../../assets/uploads/locations/5/5-intro.jpg';
import bg6 from '../../assets/uploads/locations/6/6-intro.jpg';
const ItineraryModule = () => {
    const tours = [
        {
          id: 1,
          destination: "Tháp Nghinh Phong / Gành đá đĩa / Vịnh Vũng Rô",
          image:bg1,
          departureFrom: "Hồ Chí Minh",
          duration: "3 ngày 3 đêm",
          originalPrice: "2,580,000 đ",
          salePrice: "2,380,000 đ",
          tourType: "Tour khách lẻ"
        },
        {
          id: 2,
          destination: "Đà Lạt | Vùng Đất Cổ Tích Fairytale Land",
          image: bg2,
          departureFrom: "Hồ Chí Minh",
          duration: "4 ngày 3 đêm",
          originalPrice: "3,115,000 đ",
          salePrice: "2,915,000 đ",
          tourType: "Tour khách lẻ"
        },
        {
          id: 3,
          destination: "Đà Lạt | Vườn Thượng Uyển Bay | Kokoro Coffee | Puppy Farm",
          image: bg3,
          departureFrom: "Hồ Chí Minh",
          duration: "3 ngày 3 đêm",
          originalPrice: "2,896,000 đ",
          salePrice: "2,596,000 đ",
          tourType: "Tour khách lẻ"
        },
        {
          id: 4,
          destination: "Phan Thiết | Mũi Né | Lâu Đài Rượu Vang (2N1Đ)",
          image: bg4,
          departureFrom: "Hồ Chí Minh",
          duration: "2 ngày 1 đêm",
          originalPrice: "1,960,000 đ",
          salePrice: "1,760,000 đ",
          tourType: "Tour khách lẻ"
        },
        {
          id: 5,
          destination: "Nam Cát Tiên | Nghỉ Dưỡng Resort Orchard",
          image: bg5,
          departureFrom: "Tp Hồ Chí Minh",
          duration: "2 ngày 1 đêm",
          originalPrice: "2,996,000 đ",
          salePrice: "2,596,000 đ",
          tourType: "Tour khách lẻ"
        },
        {
          id: 6,
          destination: "Mỹ Tho | Cần Thơ | Chợ Nổi Cái Răng | KDL Mỹ Khánh",
          image: bg6,
          departureFrom: "Tp Hồ Chí Minh",
          duration: "2 ngày 1 đêm",
          originalPrice: "1,850,000 đ",
          salePrice: "1,650,000 đ",
          tourType: "Tour khách lẻ"
        }
      ];
    
      return (
        <div className="container mx-auto p-4">
          {/* <h1 className="text-2xl font-bold mb-6">Tour Packages</h1> */}
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {tours.map(tour => (
              <TourCard key={tour.id} tour={tour} />
            ))}
          </div>
        </div>
      );
    };
    
    const TourCard = ({ tour }) => {
      return (
        <div className="card">
          <div className="card-img">
            <img 
              src={tour.image} 
              alt={tour.destination} 
            />
            {/* <div className="label-badge">
              Đặt Thấy Là
            </div> */}
          </div>
          
          <div className="card-body">
            <h2 className="card-title">{tour.destination}</h2>
            
            <div className="info-row">
              <span>🚌</span>
              <span>Xuất phát từ {tour.departureFrom}</span>
            </div>
            
            <div className="info-row">
              <span>🕒</span>
              <span>{tour.duration}</span>
            </div>
            
            <div className="info-row">
              <span>👥</span>
              <span>{tour.tourType}</span>
            </div>
            
            <div className="price-action">
              <div className="price-section">
                <div className="old-price">{tour.originalPrice}</div>
                <div className="new-price">{tour.salePrice}</div>
              </div>
              <button className="btn-book">
                Đặt tour
              </button>
            </div>
          </div>
        </div>
      );
    };
export default ItineraryModule;
